# Generates themes/knobs.css: per-component "looks" for Colibri UI, driven globally by <html data-ui-btn|acc|tabs|card|input="…">
# or per element via data-look="…". Selectors double the component attribute so they outrank theme-pack rules.
def S(knob, comp, val, tail=""):
    c2 = comp + comp
    return f"[{knob}={val}] {c2}:not([data-look]){tail},{c2}[data-look={val}]{tail}"
out = ["/* Colibri UI component looks (@colibri/ui/themes/knobs.css). OPTIONAL, load after colibri.css and packs.\n"
       "   Global: <html data-ui-btn=\"solid|soft|surface|outline|classic|ghost\" data-ui-acc=\"boxed|fat|skinny\" data-ui-tabs=\"underline|pill|segmented\"\n"
       "           data-ui-card=\"surface|outline|elevated|ghost|glass\" data-ui-input=\"surface|soft|underline\">\n"
       "   Per element: data-look=\"…\" on the component (wins over the global setting). Generated by tools/gen_knobs.py. */"]
def R(sel, body): out.append(sel + "{" + body + "}")
B = '[data-ui=button]'
soft_fg = "color-mix(in oklab,var(--ui-primary) 72%,var(--ui-foreground))"
looks = {
 "solid": f"background:var(--ui-primary);color:var(--ui-primary-foreground);border:1px solid var(--ui-primary);box-shadow:none",
 "soft": f"background:color-mix(in oklab,var(--ui-primary) 15%,var(--ui-background));color:{soft_fg};border:1px solid transparent;box-shadow:none",
 "surface": f"background:color-mix(in oklab,var(--ui-primary) 6%,var(--ui-background));color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 32%,var(--ui-background));box-shadow:none",
 "outline": f"background:transparent;color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 62%,var(--ui-background));box-shadow:none",
 "classic": "background:linear-gradient(180deg,color-mix(in oklab,var(--ui-primary) 82%,#fff),var(--ui-primary) 50%,color-mix(in oklab,var(--ui-primary) 88%,#000));color:var(--ui-primary-foreground);border:1px solid color-mix(in oklab,var(--ui-primary) 78%,#000);box-shadow:inset 0 1px 0 #ffffff47,0 1px 2px #0003,0 3px 8px -3px color-mix(in oklab,var(--ui-primary) 55%,transparent)",
 "ghost": f"background:transparent;color:{soft_fg};border:1px solid transparent;box-shadow:none",
}
for v, body in looks.items():
    R(S("data-ui-btn", B, v), body)
    R(S("data-ui-btn", B, v, ":hover:not(:disabled)"), "filter:brightness(.96) saturate(1.08)" if v in ("solid", "classic") else f"background:color-mix(in oklab,var(--ui-primary) {22 if v=='soft' else 12}%,var(--ui-background))")
R(f"html[data-theme=dark] {B}{B}:hover:not(:disabled)", "filter:brightness(1.1)")
for sz, (h, px, fs) in {"xs": (24, ".5rem", "11px"), "sm": (30, ".75rem", "12.5px"), "md": (36, "1rem", "14px"), "lg": (42, "1.2rem", "15px"), "xl": (50, "1.5rem", "16.5px")}.items():
    R(f"{B}{B}[data-size={sz}]", f"height:calc({h}px * var(--ui-scale,1));padding:0 {px};font-size:{fs};gap:.4em")
R(f"{B}{B}:disabled,{B}{B}[aria-disabled=true]", "opacity:.45;cursor:not-allowed;filter:saturate(.4)")
# badges
BD = "[data-ui=badge]"
for v, body in {"solid": "background:var(--ui-primary);color:var(--ui-primary-foreground);border:1px solid transparent",
                "soft": f"background:color-mix(in oklab,var(--ui-primary) 16%,var(--ui-background));color:{soft_fg};border:1px solid transparent",
                "surface": f"background:color-mix(in oklab,var(--ui-primary) 7%,var(--ui-background));color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 35%,var(--ui-background))",
                "outline": f"background:transparent;color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 60%,var(--ui-background))"}.items():
    R(f"{BD}{BD}[data-look={v}]", body)
for sz, (fs, pad) in {"sm": ("10.5px", "1px 6px"), "md": ("12px", "2px 8px"), "lg": ("13.5px", "4px 11px")}.items():
    R(f"{BD}{BD}[data-size={sz}]", f"font-size:{fs};padding:{pad}")
R(f"{BD}{BD}[data-look]", "display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:max(4px,var(--ui-radius-sm));font:500 12px/1.4 var(--ui-font);white-space:nowrap")
# callout looks
CO = "[data-ui=callout]"
for v, body in {"soft": f"background:color-mix(in oklab,var(--ui-primary) 12%,var(--ui-background))!important;border:1px solid transparent!important;color:{soft_fg}",
                "surface": f"background:color-mix(in oklab,var(--ui-primary) 6%,var(--ui-background))!important;border:1px solid color-mix(in oklab,var(--ui-primary) 30%,var(--ui-background))!important;color:{soft_fg}",
                "outline": f"background:transparent!important;border:1px solid color-mix(in oklab,var(--ui-primary) 55%,var(--ui-background))!important;color:{soft_fg}"}.items():
    R(f"{CO}{CO}[data-look={v}]", body)
R(f"{CO}{CO}[data-look] [data-ui-part=icon]", "color:var(--ui-primary)")
# accordion
A = "[data-ui=accordion]"; T = " [data-ui-part=trigger]"; I = " [data-ui-part=item]"; C = " [data-ui-part=content]"
reset_c = "border:0!important;background:none!important;box-shadow:none!important;overflow:visible!important;border-radius:0!important"
R(S("data-ui-acc", A, "fat"), "display:grid!important;gap:.6rem;" + reset_c)
R(S("data-ui-acc", A, "fat", I), "border:1px solid var(--ui-border)!important;border-radius:var(--ui-radius-lg);background:var(--ui-card);overflow:hidden;box-shadow:var(--ui-shadow-sm)")
R(S("data-ui-acc", A, "fat", T), "padding:1.05rem 1.2rem!important;font-size:calc(var(--ui-text-sm) * 1.08)!important;font-weight:600!important;background:none!important;box-shadow:none!important;text-decoration:none!important")
R(S("data-ui-acc", A, "fat", T + "[aria-expanded=true]"), "background:color-mix(in oklab,var(--ui-primary) 7%,var(--ui-card))!important;box-shadow:inset 3px 0 0 var(--ui-primary)!important")
R(S("data-ui-acc", A, "fat", C), "padding:.2rem 1.2rem 1.15rem!important;background:none!important;color:var(--ui-muted-foreground)!important;font-size:var(--ui-text-sm)!important")
R(S("data-ui-acc", A, "skinny"), reset_c)
R(S("data-ui-acc", A, "skinny", I), "border:0!important;border-bottom:1px solid var(--ui-border)!important;border-radius:0!important;background:none!important;box-shadow:none!important")
R(S("data-ui-acc", A, "skinny", T), "padding:.45rem 0!important;font-size:calc(var(--ui-text-sm) * .92)!important;font-weight:500!important;background:none!important;box-shadow:none!important")
R(S("data-ui-acc", A, "skinny", C), "padding:0 0 .6rem!important;background:none!important;font-size:calc(var(--ui-text-sm) * .9)!important;color:var(--ui-muted-foreground)!important")
R(S("data-ui-acc", A, "boxed"), "border:1px solid var(--ui-border)!important;border-radius:var(--ui-radius-lg)!important;overflow:hidden!important;background:var(--ui-card)!important;box-shadow:var(--ui-shadow-sm)!important")
R(S("data-ui-acc", A, "boxed", I), "border:0!important;border-bottom:1px solid var(--ui-border)!important;border-radius:0!important;background:none!important")
R(S("data-ui-acc", A, "boxed", I + ":last-child"), "border-bottom:0!important")
R(S("data-ui-acc", A, "boxed", T), "padding:.8rem 1rem!important;background:none!important;box-shadow:none!important;font-weight:550!important")
R(S("data-ui-acc", A, "boxed", T + "[aria-expanded=true]"), "background:var(--ui-muted)!important")
R(S("data-ui-acc", A, "boxed", C), "padding:.75rem 1rem 1rem!important;background:none!important;color:var(--ui-muted-foreground)!important")
R(f"[data-ui-acc] {A}{A}:not([data-look]){C}::before,{A}{A}[data-look]{C}::before", "display:none!important")
# tabs + tab-nav
TB = "[data-ui=tabs]"; TN = "[data-ui=tab-nav]"; L = " [data-ui-part=list]"; TR = " [data-ui-part=trigger]"; ACT = ":is([data-state=active],[aria-selected=true])"; LK = " [data-ui-part=link]"
base_tr = "font:500 var(--ui-text-sm) var(--ui-font)!important;letter-spacing:0!important;text-transform:none!important;text-decoration:none!important"
for comp, item, act, lst in ((TB, TR, ACT, L), (TN, LK, "[aria-current=page]", "")):
    R(S("data-ui-tabs", comp, "underline", lst), "display:flex!important;background:none!important;border:0!important;border-bottom:1px solid var(--ui-border)!important;border-radius:0!important;padding:0!important;gap:1.1rem!important;box-shadow:none!important")
    R(S("data-ui-tabs", comp, "underline", item), base_tr + ";background:none!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0 .1rem!important;height:40px!important;display:inline-flex!important;align-items:center;border-bottom:2px solid transparent!important;margin-bottom:-1px!important;color:var(--ui-muted-foreground)!important")
    R(S("data-ui-tabs", comp, "underline", item + act), "border-bottom-color:var(--ui-primary)!important;color:var(--ui-foreground)!important")
    R(S("data-ui-tabs", comp, "pill", lst), "display:inline-flex!important;background:none!important;border:0!important;padding:0!important;gap:.35rem!important;box-shadow:none!important")
    R(S("data-ui-tabs", comp, "pill", item), base_tr + ";border:0!important;border-radius:999px!important;background:none!important;box-shadow:none!important;padding:0 .95rem!important;height:32px!important;display:inline-flex!important;align-items:center;color:var(--ui-muted-foreground)!important")
    R(S("data-ui-tabs", comp, "pill", item + ":hover"), "background:var(--ui-muted)!important")
    R(S("data-ui-tabs", comp, "pill", item + act), "background:var(--ui-primary)!important;color:var(--ui-primary-foreground)!important")
    R(S("data-ui-tabs", comp, "segmented", lst), "display:inline-flex!important;background:var(--ui-muted)!important;border:0!important;border-radius:var(--ui-radius)!important;padding:3px!important;gap:2px!important;box-shadow:none!important")
    R(S("data-ui-tabs", comp, "segmented", item), base_tr + ";border:0!important;border-radius:var(--ui-radius-sm)!important;background:none!important;box-shadow:none!important;padding:0 .9rem!important;height:30px!important;display:inline-flex!important;align-items:center;color:var(--ui-muted-foreground)!important")
    R(S("data-ui-tabs", comp, "segmented", item + act), "background:var(--ui-background)!important;color:var(--ui-foreground)!important;box-shadow:var(--ui-shadow-sm)!important")
for v in ("underline","pill","segmented"): R(S("data-ui-tabs", TN, v, LK + "::after") + "," + S("data-ui-tabs", TN, v, LK + "::before"), "display:none!important")
for v in ("pill","segmented"): R(S("data-ui-tabs", TN, v), "border-bottom:0!important")
R(f"[data-ui-tabs] {TB}{TB}:not([data-look]) [data-ui-part=panel],{TB}{TB}[data-look] [data-ui-part=panel]", "background:none!important;border:0!important;box-shadow:none!important;padding:.9rem .1rem 0!important")
R(f"[data-ui-tabs] {TN}{TN}:not([data-look]),{TN}{TN}[data-look]", "display:flex;background:none;border:0;padding:0;box-shadow:none")
# cards
CD = ":is([data-ui=card],.card)"
for v, body in {"outline": "background:var(--ui-background)!important;border:1px solid var(--ui-border)!important;box-shadow:none!important",
                "elevated": "background:var(--ui-card)!important;border:1px solid transparent!important;box-shadow:var(--ui-shadow)!important",
                "ghost": "background:transparent!important;border:1px solid transparent!important;box-shadow:none!important",
                "glass": "background:color-mix(in oklab,var(--ui-card) 55%,transparent)!important;border:1px solid color-mix(in oklab,var(--ui-foreground) 11%,transparent)!important;box-shadow:var(--ui-shadow-sm),inset 0 1px 0 color-mix(in oklab,#fff 14%,transparent)!important;backdrop-filter:blur(16px) saturate(1.5)",
                "surface": "background:var(--ui-card)!important;border:1px solid var(--ui-border)!important;box-shadow:var(--ui-shadow-sm)!important"}.items():
    R(f"[data-ui-card={v}] {CD}{CD}:not([data-look]),{CD}{CD}[data-look={v}]", body)
# inputs
IN = ":is(input:not([type=checkbox],[type=radio],[type=range],[type=color],[type=file]),select,textarea)"
R(f"[data-ui-input=soft] {IN}{IN}:not([data-look]),{IN}{IN}[data-look=soft]", "background:color-mix(in oklab,var(--ui-primary) 5%,var(--ui-muted))!important;border-color:transparent!important")
R(f"[data-ui-input=underline] {IN}{IN}:not([data-look]),{IN}{IN}[data-look=underline]", "border-width:0 0 1.5px!important;border-radius:0!important;background:transparent!important;padding-inline:2px!important;box-shadow:none")
R(f"[data-ui-input=underline] {IN}{IN}:not([data-look]):focus-visible,{IN}{IN}[data-look=underline]:focus-visible", "border-color:var(--ui-primary)!important;box-shadow:0 1.5px 0 var(--ui-primary)!important")
R(f"[data-ui-input=surface] {IN}{IN}:not([data-look]),{IN}{IN}[data-look=surface]", "background:var(--ui-background)!important;border:1px solid var(--ui-input)!important")
# heading knobs (Studio typography dials)
R(":where(.ui-root) :where(h1,h2,h3,h4)", "font-family:var(--st-hfont,inherit);font-weight:var(--st-hweight,revert)")
import os; open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "themes", "knobs.css"), "w").write("\n".join(out) + "\n")
print(len(out), "rules")
